			tab_next(self);

			tab_control_meter(self);
			draw_meter(self, StringType("tlextmirrorblur"), sVar(dx), sVar(dy), sVar(dw), round(ext.mirror_blur * 100.0), IntType(0), IntType(100), IntType(0), IntType(1), GetExtTbx(21, true), IntType(2949));
			tab_next(self);

