			IntType ax = std::clamp((int)ext.mirror_axis, 0, 2);
			tab_control_menu(self);
			draw_button_menu(self, { StringType("tlextmirroraxis"), e_menu_LIST, sVar(dx), sVar(dy), sVar(dw), IntType(24), ax, StringType(axisNames[ax]), IntType(2912) });
